    static int a[20000];
    static int b[20000];
    static int d[20000];
    static int e[20000];
    int i = 0, n = 0, x = 0, y = 0, z = 0;
    n = read();
    // 初始化 x=f(0)、y=f(1)，零阶空走法计为一种。
    x = 1;
    y = 1;
